  "CREATE TRIGGER IF NOT EXISTS document_pin_contribution_insert AFTER INSERT ON document_transcript_pins\n      BEGIN INSERT INTO document_pin_totals(project_id,session_id,role,prompt_identity_scheme,transcripts)\n  VALUES(NEW.project_id,NEW.session_id,NEW.role,NEW.prompt_identity_scheme,1)\n  ON CONFLICT(project_id,session_id,role,prompt_identity_scheme) DO UPDATE SET transcripts=transcripts+excluded.transcripts;\n  DELETE FROM document_pin_totals WHERE (project_id,session_id,role,prompt_identity_scheme)=(NEW.project_id,NEW.session_id,NEW.role,NEW.prompt_identity_scheme) AND transcripts=0; INSERT INTO document_group_pins(project_id,session_id,agent,scheme,conflict,read_before)\n  VALUES(NEW.project_id,NEW.session_id,NEW.agent,NULLIF(NEW.prompt_identity_scheme,''),0,NEW.read_before)\n  ON CONFLICT(project_id,session_id,agent) DO UPDATE SET scheme=COALESCE(scheme,excluded.scheme),\n    conflict=conflict OR (scheme IS NOT NULL AND excluded.scheme IS NOT NULL AND scheme<>excluded.scheme),\n    read_before=MAX(read_before,excluded.read_before)\n  WHERE (scheme IS NULL AND excluded.scheme IS NOT NULL) OR (conflict=0 AND scheme IS NOT NULL AND excluded.scheme IS NOT NULL AND scheme<>excluded.scheme)\n    OR read_before<excluded.read_before; END",
  "CREATE TRIGGER IF NOT EXISTS document_pin_source_insert AFTER INSERT ON transcripts\n      BEGIN DELETE FROM document_transcript_pins WHERE (project_id,transcript_id) IN (SELECT NEW.project_id project_id,NEW.transcript_id transcript_id)\n      AND NOT EXISTS(SELECT 1 FROM transcripts t WHERE (t.project_id,t.transcript_id)=(document_transcript_pins.project_id,document_transcript_pins.transcript_id));INSERT INTO document_transcript_pins(project_id,transcript_id,session_id,agent,prompt_identity_scheme,record_identity_scheme,role,read_before) SELECT project_id,transcript_id,session_id,agent,prompt_identity_scheme,record_identity_scheme,role,read_before FROM (SELECT t.project_id,t.transcript_id,t.session_id,COALESCE(t.agent,'') agent,\n    COALESCE(t.prompt_identity_scheme,'') prompt_identity_scheme,t.record_identity_scheme,COALESCE(t.role,'') role,\n    (t.prompt_identity_scheme IS NULL AND (t.parser_version>0 OR t.parsed_at IS NOT NULL OR t.parsed_offset>0)) read_before\n    FROM (SELECT NEW.project_id project_id,NEW.transcript_id transcript_id) k CROSS JOIN transcripts t ON (t.project_id,t.transcript_id)=(k.project_id,k.transcript_id)) WHERE true\n      ON CONFLICT(project_id,transcript_id) DO UPDATE SET session_id=excluded.session_id,agent=excluded.agent,prompt_identity_scheme=excluded.prompt_identity_scheme,record_identity_scheme=excluded.record_identity_scheme,role=excluded.role,read_before=excluded.read_before\n      WHERE (document_transcript_pins.session_id,document_transcript_pins.agent,document_transcript_pins.prompt_identity_scheme,document_transcript_pins.record_identity_scheme,document_transcript_pins.role,document_transcript_pins.read_before) IS NOT (excluded.session_id,excluded.agent,excluded.prompt_identity_scheme,excluded.record_identity_scheme,excluded.role,excluded.read_before); END",
  "CREATE TRIGGER IF NOT EXISTS document_pin_contribution_update AFTER UPDATE ON document_transcript_pins\n      BEGIN INSERT INTO document_pin_totals(project_id,session_id,role,prompt_identity_scheme,transcripts)\n  VALUES(OLD.project_id,OLD.session_id,OLD.role,OLD.prompt_identity_scheme,-1)\n  ON CONFLICT(project_id,session_id,role,prompt_identity_scheme) DO UPDATE SET transcripts=transcripts+excluded.transcripts;\n  DELETE FROM document_pin_totals WHERE (project_id,session_id,role,prompt_identity_scheme)=(OLD.project_id,OLD.session_id,OLD.role,OLD.prompt_identity_scheme) AND transcripts=0;INSERT INTO document_pin_totals(project_id,session_id,role,prompt_identity_scheme,transcripts)\n  VALUES(NEW.project_id,NEW.session_id,NEW.role,NEW.prompt_identity_scheme,1)\n  ON CONFLICT(project_id,session_id,role,prompt_identity_scheme) DO UPDATE SET transcripts=transcripts+excluded.transcripts;\n  DELETE FROM document_pin_totals WHERE (project_id,session_id,role,prompt_identity_scheme)=(NEW.project_id,NEW.session_id,NEW.role,NEW.prompt_identity_scheme) AND transcripts=0; INSERT INTO document_group_pins(project_id,session_id,agent,scheme,conflict,read_before)\n  VALUES(NEW.project_id,NEW.session_id,NEW.agent,NULLIF(NEW.prompt_identity_scheme,''),0,NEW.read_before)\n  ON CONFLICT(project_id,session_id,agent) DO UPDATE SET scheme=COALESCE(scheme,excluded.scheme),\n    conflict=conflict OR (scheme IS NOT NULL AND excluded.scheme IS NOT NULL AND scheme<>excluded.scheme),\n    read_before=MAX(read_before,excluded.read_before)\n  WHERE (scheme IS NULL AND excluded.scheme IS NOT NULL) OR (conflict=0 AND scheme IS NOT NULL AND excluded.scheme IS NOT NULL AND scheme<>excluded.scheme)\n    OR read_before<excluded.read_before; END",
