  "CREATE TABLE IF NOT EXISTS document_failure_contributions(project_id TEXT NOT NULL CHECK (project_id NOT GLOB '*[^A-Za-z0-9._-]*' AND length(project_id) BETWEEN 1 AND 64 AND project_id NOT IN ('.', '..')),\n      transcript_id TEXT NOT NULL,generation INTEGER NOT NULL,session_id TEXT NOT NULL,failure TEXT NOT NULL,\n      updated_at INTEGER NOT NULL,diagnostic TEXT,PRIMARY KEY(project_id,transcript_id,generation)) WITHOUT ROWID",
